    'CHECK(from_stage_kind IN (\'newAyah\', \'cumulative\', \'reviewRange\', \'bridge\', \'sectionReview\', \'finalReview\'))',
    'CHECK(to_stage_kind IN (\'newAyah\', \'cumulative\', \'reviewRange\', \'bridge\', \'sectionReview\', \'finalReview\'))',
    'CHECK(from_stage_start_ayah > 0 AND from_stage_end_ayah >= from_stage_start_ayah)',
    'CHECK(to_stage_start_ayah > 0 AND to_stage_end_ayah >= to_stage_start_ayah)',
    'CHECK(reason IS NULL OR length(reason) > 0)',
  ];
  @override
  bool get dontWriteConstraints => true;
}

